import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        # remove build metadata first
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main = core
        major, minor, patch = (int(x) for x in main.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare_ident(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai < bi: return -1
            if ai > bi: return 1
            return 0
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        if a < b: return -1
        if a > b: return 1
        return 0

    def compare(v1, v2):
        maj1, min1, pat1, pre1 = parse(v1)
        maj2, min2, pat2, pre2 = parse(v2)
        if maj1 != maj2: return -1 if maj1 < maj2 else 1
        if min1 != min2: return -1 if min1 < min2 else 1
        if pat1 != pat2: return -1 if pat1 < pat2 else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None and pre2 is not None:
            return 1
        if pre1 is not None and pre2 is None:
            return -1
        for i1, i2 in zip(pre1, pre2):
            c = compare_ident(i1, i2)
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    return sorted(versions, key=functools.cmp_to_key(compare))

